from pathlib import Path
import hashlib, json, html
root=Path(__file__).resolve().parents[1]
out=root/'artifacts/feedback-polish-review'
report=json.loads((out/'inspection.json').read_text())
files=[('Upgrade actions','reference-level-layout.png'),('Shop prices','tier-shop.png'),('Achievement notification and ground details','achievement-toast.png'),('Crate icons; inventory strip removed','crate-icons.png'),('Six-particle pickup burst at 0.09 seconds','pickup-burst.png'),('Independent music volume','options-sound.png')]
body=''.join(f'<section><h2>{html.escape(title)}</h2><a href="{name}"><img src="{name}"></a></section>' for title,name in files)
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><title>Scrapshift — feedback polish</title>
<style>body{{background:#14151a;color:#eee;font:18px system-ui;max-width:1400px;margin:40px auto;padding:0 24px}}img{{width:100%;border-radius:10px}}a{{color:#a9daed}}section{{margin:40px 0}}audio{{width:100%;max-width:650px}}p{{line-height:1.6}}</style>
<h1>Feedback polish</h1><p>Runtime captures: {report['status']} ({len(report['checks'])} cases). These are staged renders from the executable; they do not certify native input or subjective sound quality.</p>
<p>Reference: <a href="../base-release-ui/reference-2.png">Brotato upgrade screen</a> · <a href="../base-release-ui/reference-3.png">Brotato shop</a>. Button actions use gray idle surfaces and white hover. Our character and item art remain.</p>
<h2>Neon Salvage — original score</h2><p>126 BPM, E minor, 32-bar electronic loop. Music continues quietly through menus and pause. Adjust Music volume in Options → Sound.</p><audio controls src="../../Assets/Scrapshift/Resources/Music/NeonSalvage.wav"></audio>
<h2>Consumable crunch preview</h2><audio controls src="../../Assets/Scrapshift/Content/Audio/Consume_01.wav"></audio>
{body}<p><a href="inspection.json">Runtime report</a> · <a href="audio-runtime.json">Audio output report</a></p></html>'''
(out/'review.html').write_text(page,encoding='utf-8')
provenance=[]
for i in range(1,4):
    source=Path(f'E:/UnityProjects/brotato-(3.x)/items/consumables/fruit/comedy_bite_chew_{i:02}.wav')
    dest=root/f'Assets/Scrapshift/Content/Audio/Consume_{i:02}.wav'
    source_hash=hashlib.sha256(source.read_bytes()).hexdigest();dest_hash=hashlib.sha256(dest.read_bytes()).hexdigest()
    assert source_hash==dest_hash
    provenance.append(dict(source=str(source),asset=str(dest.relative_to(root)),sha256=dest_hash))
(out/'audio-provenance.json').write_text(json.dumps({'authorization':'User explicitly requested the supplied reference eating sounds. Local reference-use provenance; no distribution license asserted.','consumables':provenance,'music':'Original synthesized score generated by scripts/compose_music.py; no reference audio samples or melodies.'},indent=2)+'\n')
print(out/'review.html')
